1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4		<meta charset="utf-8">
5		<meta name="viewport" content="width=device-width, initial-scale=1">
6		<meta name="description" content="A properly structured HTML5 document.">
7		<meta name="color-scheme" content="light dark">
8		<meta name="theme-color" content="#ffffff" media="(prefers-color-scheme: light)">
9		<meta name="theme-color" content="#121212" media="(prefers-color-scheme: dark)">
10		<title>Welcome</title>
11		<style>
12			:root {
13				color-scheme: light dark;
14				--text: #333;
15				--background: #fff;
16				--accent: #0066cc;
17			}
18			@media (prefers-color-scheme: dark) {
19				:root {
20					--text: #ddd;
21					--background: #121212;
22					--accent: #66b3ff;
23				}
24			}
25			*,
26			*::before,
27			*::after {
28				box-sizing: border-box;
29			}
30			body {
31				font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
32				line-height: 1.6;
33				max-width: 70ch;
34				margin: 0 auto;
35				padding: max(1.25rem, env(safe-area-inset-top)) max(1.25rem, env(safe-area-inset-right)) max(1.25rem, env(safe-area-inset-bottom)) max(1.25rem, env(safe-area-inset-left));
36				color: var(--text);
37				background: var(--background);
38				-webkit-text-size-adjust: 100%;
39				text-size-adjust: 100%;
40			}
41			h1 {
42				color: var(--accent);
43				line-height: 1.2;
44				text-wrap: balance;
45			}
46			p {
47				text-wrap: pretty;
48			}
49			a {
50				color: var(--accent);
51				text-underline-offset: 0.15em;
52			}
53			:focus-visible {
54				outline: 2px solid var(--accent);
55				outline-offset: 2px;
56			}
57			.skip-link {
58				position: absolute;
59				left: -9999px;
60				top: 0;
61				background: var(--background);
62				color: var(--text);
63				padding: 0.5rem 1rem;
64				z-index: 1;
65			}
66			.skip-link:focus {
67				left: 0.5rem;
68			}
69			header,
70			footer {
71				padding-block: 1rem;
72			}
73			footer {
74				border-top: 1px solid color-mix(in srgb, var(--text) 20%, transparent);
75				font-size: 0.875rem;
76				color: color-mix(in srgb, var(--text) 70%, transparent);
77			}
78		</style>
79	</head>
80	<body>
81		<a class="skip-link" href="#main">Skip to content</a>
82		<header>
83			<h1>Welcome</h1>
84		</header>
85		<main id="main">
86			<p>This is a properly structured HTML5 document.</p>
87			<p>
88				It uses semantic landmarks, a skip link for keyboard users,
89				and CSS that adapts to the visitor's light or dark mode preference.
90			</p>
91		</main>
92		<footer>
93			<p>&copy; 2026. All rights reserved.</p>
94		</footer>
95	</body>
96	</html>
